  --panel-edge: rgba(255, 204, 102, .36);
  --text: #fffdf4;
  --muted: rgba(255, 248, 224, .55);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #03040a; }
body {
  font-family: var(--body);
  color: var(--text);
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #03040a;
  transition: background .9s ease;
}
#stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}
.atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 30%, rgba(0,0,0,.15) 75%, rgba(0,0,0,.65) 100%),
    linear-gradient(180deg, rgba(0,0,0,.24), transparent 22%, transparent 72%, rgba(0,0,0,.4));
  mix-blend-mode: multiply;
}
#app[data-era="0"] .atmosphere,
#app[data-era="1"] .atmosphere {
  opacity: .26;
  mix-blend-mode: multiply;
}
#app[data-era="2"] .atmosphere { opacity: .85; }
#app[data-era="3"] .atmosphere { opacity: .7; }
#app[data-era="4"] .atmosphere { opacity: .5; }
#app[data-era="5"] .atmosphere { opacity: .8; }

.screen { position: absolute; inset: 0; z-index: 5; transition: opacity .45s ease, visibility .45s; }
.hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

/* ───────────────────────── MENU ───────────────────────── */
.menu {
  z-index: 10;
  background:
    linear-gradient(90deg, rgba(2,3,8,.64) 0%, rgba(2,3,8,.08) 58%, rgba(2,3,8,.45) 100%),
    linear-gradient(180deg, rgba(2,3,8,.55) 0%, transparent 28%, transparent 58%, rgba(2,3,8,.9) 100%);
  pointer-events: none;
}
.menu::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .18;
  background-image: repeating-linear-gradient(0deg, transparent 0 3px, rgba(255,255,255,.045) 3px 4px);
  mix-blend-mode: screen;
}
.menu > * { pointer-events: auto; }
.menu-top {
  position: absolute;
  top: calc(var(--safe-top) + 20px);
  left: max(20px, 4vw);
  right: max(20px, 4vw);
  display: flex;
  align-items: center;
  justify-content: space-between;
  z-index: 3;
}
.brand { display: flex; align-items: center; gap: 11px; }
.brand-mark { display: flex; flex-direction: column; gap: 3px; transform: skewX(-16deg); }
.brand-mark i { display: block; width: 21px; height: 3px; background: var(--accent); box-shadow: 0 0 16px rgba(var(--accent-rgb), .7); }
.brand-mark i:nth-child(2) { width: 14px; opacity: .7; }
.brand-mark i:nth-child(3) { width: 7px; opacity: .4; }
.brand-text {
  font-family: var(--micro);
  font-size: 8px;
  line-height: 1.55;
  letter-spacing: .17em;
  color: rgba(255,255,255,.58);
}
.brand-text b { color: #fff; font-weight: 600; letter-spacing: .22em; }
.menu-top-actions { display: flex; align-items: center; gap: 12px; }
.live-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--micro);
  font-size: 7px;
  letter-spacing: .14em;
  color: rgba(255,255,255,.5);
}
.live-pill i { width: 5px; height: 5px; border-radius: 50%; background: #68ffb2; box-shadow: 0 0 10px #68ffb2; animation: pulse 2s infinite; }
.icon-btn {
  width: 36px; height: 36px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(3,5,12,.3);
  backdrop-filter: blur(8px);
  transition: border-color .2s, background .2s;
}
.icon-btn:hover { border-color: var(--accent); background: rgba(var(--accent-rgb), .12); }
.icon-btn svg { width: 15px; fill: rgba(255,255,255,.78); }
.icon-btn.muted svg { opacity: .35; }
.icon-btn.muted::after {
  content: ''; position: absolute; width: 19px; height: 1px; background: var(--accent); transform: rotate(-45deg);
}

.menu-copy {
  position: absolute;
  left: max(20px, 5vw);
  top: calc(var(--safe-top) + 14vh);
  z-index: 2;
  max-width: min(700px, 78vw);
  pointer-events: none;
}
.eyebrow {
  display: flex; align-items: center; gap: 9px;
  font-family: var(--micro);
  font-size: 8px;
  letter-spacing: .19em;
  color: rgba(255,255,255,.55);
  margin-bottom: 15px;
  text-shadow: 0 2px 18px #000;
}
.eyebrow b { color: var(--accent); }
.pulse-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 0 rgba(var(--accent-rgb), .6); animation: ring-pulse 2.4s infinite; }
.menu h1 {
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(74px, 14.4vw, 168px);
  line-height: .72;
  letter-spacing: .015em;
  margin: 0;
  padding: 0;
  filter: drop-shadow(0 12px 30px rgba(0,0,0,.55));
}
.menu h1 span {
  display: block;
  color: #f7f8ff;
  text-shadow: 0 0 50px rgba(255,255,255,.12);
}
.menu h1 em {
  display: block;
  font-style: normal;
  color: var(--accent);
  -webkit-text-stroke: 1px rgba(255,255,255,.18);
  text-shadow: 0 0 40px rgba(var(--accent-rgb), .4);
  transform: translateX(.06em) scaleY(1.04);
  transform-origin: left top;
}
.title-rule { display: flex; align-items: center; gap: 12px; margin: 17px 0 14px; max-width: 390px; }
.title-rule span { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, rgba(255,255,255,.45)); }
.title-rule span:last-child { background: linear-gradient(90deg, rgba(255,255,255,.45), transparent); }
.title-rule strong {
  font-family: var(--micro);
  font-size: clamp(8px, 1.3vw, 11px);
  font-weight: 400;
  letter-spacing: .62em;
  color: rgba(255,255,255,.82);
  padding-left: .62em;
}
.tagline {
  font-size: 15px;
  line-height: 1.35;
  font-weight: 500;
  color: rgba(244,247,255,.65);
  margin: 0;
  letter-spacing: .04em;
  text-shadow: 0 2px 16px #000;
}
.tagline::before { content: ''; display: block; width: 26px; height: 2px; margin-bottom: 10px; background: var(--accent); box-shadow: 0 0 12px var(--accent); }

.menu-bottom {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 18px);
  transform: translateX(-50%);
  width: min(520px, calc(100vw - 34px));
  z-index: 4;
  display: flex;
  flex-direction: column;
  gap: 11px;
}
.run-stats { display: flex; gap: 6px; }
.run-stats > div {
  flex: 1;
  display: flex; flex-direction: column; gap: 2px;
  padding: 7px 10px;
  border-top: 1px solid rgba(255,255,255,.14);
  background: linear-gradient(180deg, rgba(255,255,255,.035), transparent);
}
.run-stats span { font-family: var(--micro); font-size: 6.5px; letter-spacing: .13em; color: rgba(255,255,255,.42); }
.run-stats strong { font-family: var(--display); font-size: 22px; font-weight: 400; line-height: 1; color: #fff; letter-spacing: .06em; }
.run-stats > div:nth-child(2) strong { color: var(--accent); }
.cta {
  position: relative;
  width: 100%;
  height: clamp(66px, 9.2vh, 82px);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: 0 28px;
  overflow: hidden;
  background: linear-gradient(100deg, var(--accent), #ff7c4f 55%, #ffb88b);
  color: #0a0810;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 15px), calc(100% - 18px) 100%, 0 100%);
  box-shadow: 0 18px 50px rgba(var(--accent-rgb), .3);
  transition: transform .18s ease, filter .18s ease;
}
#app[data-era] .menu .cta { background: linear-gradient(100deg, #ff3d74, #ff7a39 58%, #ffc36b); }
.cta:hover { transform: translateY(-2px); filter: brightness(1.08); }
.cta:active { transform: translateY(1px) scale(.995); }
.cta-shine {
  position: absolute; inset: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255,255,255,.7) 48%, transparent 60%);
  transform: translateX(-130%);
  animation: shine 5.2s infinite;
  mix-blend-mode: overlay;
}
.cta-label { font-family: var(--display); font-size: 40px; line-height: .85; letter-spacing: .1em; position: relative; }
.cta-sub { font-family: var(--micro); font-size: 7px; letter-spacing: .21em; font-weight: 600; margin-top: 7px; position: relative; opacity: .7; }
.cta-sub b { font-size: 14px; position: relative; top: 2px; margin-left: 7px; }
.menu-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.ghost-btn {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid rgba(255,255,255,.18);
  background: rgba(3,5,12,.34);
  backdrop-filter: blur(10px);
  font-family: var(--micro);
  font-size: 7.5px;
  letter-spacing: .13em;
  color: rgba(255,255,255,.75);
  transition: color .2s, border-color .2s, background .2s;
}
.ghost-btn span { color: var(--accent); font-size: 11px; }
.ghost-btn:hover { color: #fff; border-color: var(--accent); background: rgba(var(--accent-rgb), .12); }
.ghost-btn.wide { width: 100%; }
.era-strip { display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px; }
.era-chip {
  height: 30px;
  display: flex; align-items: center; justify-content: center; gap: 5px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(3,5,12,.36);
  font-family: var(--micro);
  font-size: 7px;
  letter-spacing: .08em;
  color: rgba(255,255,255,.38);
  transition: .25s ease;
  position: relative;
  overflow: hidden;
}
.era-chip::before { content: attr(data-symbol); font-size: 11px; color: rgba(255,255,255,.52); }
.era-chip.seen { color: #fff; border-color: rgba(var(--accent-rgb), .35); background: rgba(var(--accent-rgb), .08); }
.era-chip.seen::before { color: var(--accent); }
.era-chip.active { border-color: var(--accent); box-shadow: inset 0 0 16px rgba(var(--accent-rgb), .16); }

/* ───────────────────────── HUD ───────────────────────── */
.hud { pointer-events: none; z-index: 20; }
.hud > * { pointer-events: auto; }
.hud-top {
  position: absolute;
  top: calc(var(--safe-top) + 15px);
  left: max(14px, calc(50vw - 360px));
  right: max(14px, calc(50vw - 360px));
  display: grid;
  grid-template-columns: minmax(130px, 1fr) auto minmax(105px, .8fr);
  gap: 12px;
  align-items: start;
}
.hp-card {
  padding: 8px 10px 7px;
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  border-left: 3px solid var(--accent);
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 28px rgba(0,0,0,.18);
}
.hp-copy { display: flex; justify-content: space-between; align-items: baseline; }
.hp-copy span { font-family: var(--micro); font-size: 6.5px; letter-spacing: .13em; color: var(--muted); }
.hp-copy strong { font-family: var(--display); font-size: 23px; line-height: .8; letter-spacing: .05em; }
.hp-bar { position: relative; height: 6px; margin-top: 6px; background: rgba(127,127,127,.22); overflow: hidden; }
.hp-bar i { position: absolute; inset: 0; width: 100%; background: linear-gradient(90deg, var(--accent), #ffb058); transform-origin: left; transition: transform .2s ease; box-shadow: 0 0 12px rgba(var(--accent-rgb), .7); }
.hp-bar b { position: absolute; inset: 0; width: 100%; background: var(--accent-2); transform-origin: left; opacity: .48; transition: transform .25s ease; }
.hp-shield { display: flex; align-items: center; gap: 6px; margin-top: 5px; }
.hp-shield span { font-family: var(--micro); font-size: 5.5px; letter-spacing: .12em; color: var(--muted); }
.hp-shield > i { flex: 1; height: 2px; background: rgba(127,127,127,.2); }
.hp-shield > i b { display: block; height: 100%; width: 100%; background: var(--accent-2); opacity: .7; transform-origin: left; transition: transform .25s; }
.pause-btn {
  width: 32px; height: 32px;
  margin-top: 4px;
  border: 1px solid var(--panel-edge);
  background: var(--panel);
  display: flex; align-items: center; justify-content: center; gap: 4px;
  backdrop-filter: blur(9px);
}
.pause-btn i { width: 3px; height: 10px; background: var(--text); display: block; }
.score-card {
  justify-self: end;
  text-align: right;
  padding: 5px 0 4px 12px;
  border-right: 2px solid var(--accent);
  text-shadow: 0 2px 16px rgba(0,0,0,.4);
}
.score-card span { display: block; font-family: var(--micro); font-size: 6px; letter-spacing: .18em; color: var(--muted); }
.score-card strong { display: block; font-family: var(--display); font-size: 32px; line-height: .9; letter-spacing: .07em; font-weight: 400; }
.score-card em { display: block; font-family: var(--micro); font-style: normal; font-size: 7px; color: var(--accent); letter-spacing: .1em; margin-top: 2px; }

.evo-card {
  position: absolute;
  top: calc(var(--safe-top) + 85px);
  left: 50%;
  width: min(440px, calc(100vw - 38px));
  transform: translateX(-50%);
  padding: 8px 12px 9px;
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  backdrop-filter: blur(10px);
  box-shadow: 0 10px 35px rgba(0,0,0,.18);
  transition: background .5s, border-color .5s;
}
.evo-copy { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 6px; }
.evo-copy span { font-family: var(--micro); font-size: 7px; letter-spacing: .13em; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.evo-copy b { font-family: var(--display); font-size: 17px; font-weight: 400; color: var(--accent); line-height: .8; }
.evo-track { display: flex; gap: 3px; height: 4px; }
.evo-track i { flex: 1; background: rgba(127,127,127,.24); position: relative; overflow: hidden; }
.evo-track i::after { content: ''; position: absolute; inset: 0; background: var(--accent); transform-origin: left; transform: scaleX(var(--fill, 0)); transition: transform .3s ease; box-shadow: 0 0 10px var(--accent); }
.evo-track i.done::after { transform: scaleX(1); }
.evo-track i.current::after { background: linear-gradient(90deg, var(--accent), #fff); }
.sector-row {
  position: absolute;
  top: calc(var(--safe-top) + 132px);
  left: 50%;
  transform: translateX(-50%);
  width: min(380px, calc(100vw - 70px));
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--micro);
  font-size: 6px;
  letter-spacing: .16em;
  color: var(--muted);
  text-shadow: 0 2px 10px rgba(0,0,0,.35);
}
.sector-row i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, var(--panel-edge), transparent); }

.boss-hud {
  position: absolute;
  top: calc(var(--safe-top) + 155px);
  left: 50%;
  transform: translateX(-50%);
  width: min(490px, calc(100vw - 36px));
  transition: .3s ease;
}
.boss-copy { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 5px; }
.boss-copy span { font-family: var(--micro); font-size: 8px; letter-spacing: .17em; color: #ffdfaf; text-shadow: 0 0 12px var(--accent); }
.boss-copy b { font-family: var(--micro); font-size: 6px; letter-spacing: .2em; color: var(--accent); }
.boss-bar { height: 8px; background: rgba(0,0,0,.45); border: 1px solid rgba(255,255,255,.18); padding: 1px; }
.boss-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #ff5b2d, var(--accent), #ffe3a3); transform-origin: left; transition: transform .15s; box-shadow: 0 0 18px rgba(var(--accent-rgb), .65); }

.controls {
  position: absolute;
  left: max(12px, calc(50vw - 380px));
  right: max(12px, calc(50vw - 380px));
  bottom: calc(var(--safe-bottom) + 13px);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
}
.steer {
  width: 66px; height: 66px;
  border: 1px solid var(--panel-edge);
  background: var(--panel);
  backdrop-filter: blur(10px);
  display: grid; place-items: center;
  font-family: var(--display);
  font-size: 38px;
  line-height: .8;
  color: var(--text);
  padding-bottom: 5px;
  touch-action: none;
  box-shadow: 0 10px 30px rgba(0,0,0,.15);
  transition: background .12s, transform .12s;
}
.steer:active, .steer.held { background: rgba(var(--accent-rgb), .26); transform: scale(.95); }
.drag-chip {
  align-self: flex-end;
  margin-bottom: 10px;
  padding: 5px 11px;
  font-family: var(--micro);
  font-size: 6px;
  letter-spacing: .14em;
  color: var(--muted);
  background: rgba(0,0,0,.28);
  border: 1px solid var(--panel-edge);
  backdrop-filter: blur(8px);
}
.drag-chip span { color: var(--accent); font-size: 10px; }
.power-rail {
  position: absolute;
  right: max(12px, calc(50vw - 370px));
  top: 46%;
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: flex-end;
}
.power-pip {
  display: flex; align-items: center; gap: 6px;
  font-family: var(--micro); font-size: 5.5px; letter-spacing: .1em;
  color: var(--muted);
  animation: pip-in .35s ease both;
}
.power-pip b { color: var(--accent); font-size: 7px; }
.hint {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 102px);
  transform: translateX(-50%);
  padding: 7px 16px;
  background: var(--panel);
  border-top: 1px solid var(--accent);
  font-family: var(--micro);
  font-size: 7px;
  letter-spacing: .18em;
  color: var(--text);
  white-space: nowrap;
  transition: opacity .3s, transform .3s;
  box-shadow: 0 10px 30px rgba(0,0,0,.2);
}
.hint.show { animation: hint-in .35s ease both; }

.floaters { position: absolute; inset: 0; z-index: 19; pointer-events: none; overflow: hidden; }
.float-text {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: var(--display);
  font-size: 25px;
  color: #fff;
  letter-spacing: .05em;
  text-shadow: 0 0 10px rgba(0,0,0,.8), 0 2px 3px #000;
  animation: float-up .75s ease-out forwards;
  white-space: nowrap;
}
.float-text.crit { color: #ffe071; font-size: 34px; }
.float-text.gate { font-family: var(--micro); font-size: 9px; letter-spacing: .15em; color: var(--accent-2); }

/* ───────────────────────── EVOLUTION ───────────────────────── */
.evolve-overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: radial-gradient(circle at center, rgba(var(--accent-rgb), .22), rgba(0,0,0,.3) 45%, rgba(0,0,0,.7));
  transition: opacity .3s ease;
}
.evo-scan {
  position: absolute; inset: -20%;
  background: repeating-linear-gradient(0deg, transparent 0 8px, rgba(255,255,255,.16) 8px 9px);
  animation: scan-jump .5s steps(4) infinite;
  opacity: .2;
  mix-blend-mode: overlay;
}
.evo-burst {
  position: absolute; width: 100vmax; height: 100vmax;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.5);
  animation: evo-burst 1.1s ease-out forwards;
  box-shadow: 0 0 80px rgba(var(--accent-rgb), .45), inset 0 0 80px rgba(var(--accent-rgb), .25);
}
.evo-content { position: relative; text-align: center; padding: 20px; animation: evo-copy 1.15s cubic-bezier(.2,.8,.2,1) both; }
.evo-content > span { font-family: var(--micro); font-size: 8px; letter-spacing: .45em; color: var(--accent-2); }
.evo-content h2 {
  font-family: var(--display); font-weight: 400; font-size: clamp(50px, 11vw, 110px);
  line-height: .9; letter-spacing: .03em; margin: 12px 0 10px; color: #fff;
  text-shadow: 0 0 50px rgba(var(--accent-rgb), .75), 0 6px 30px rgba(0,0,0,.7);
}
.evo-line { display: flex; align-items: center; justify-content: center; gap: 10px; }
.evo-line::before, .evo-line::after { content: ''; width: 60px; height: 1px; background: linear-gradient(90deg, transparent, var(--accent)); }
.evo-line::after { background: linear-gradient(90deg, var(--accent), transparent); }
.evo-line i { width: 5px; height: 5px; background: var(--accent); transform: rotate(45deg); }
.evo-content p { font-family: var(--micro); font-size: 7px; letter-spacing: .2em; color: rgba(255,255,255,.7); margin: 12px 0 0; }

/* ───────────────────────── MODALS ───────────────────────── */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(var(--safe-top) + 18px) 16px calc(var(--safe-bottom) + 18px);
  background: rgba(2, 4, 10, .68);
  backdrop-filter: blur(12px);
  transition: opacity .3s ease, visibility .3s;
}
.modal {
  position: relative;
  width: min(430px, 100%);
  max-height: 100%;
  overflow: auto;
  padding: clamp(22px, 5vw, 36px) clamp(18px, 4.2vw, 30px);
  background:
    linear-gradient(160deg, rgba(255,255,255,.065), transparent 40%),
    var(--panel-solid);
